// A reader over a checkout on disk. It takes the file API as a parameter, because the `$` calls are in `mod.ts`.

import type { Entry, Reader } from "../domain/discover.ts";

/** The part of the file API of the engine that the reader uses. */
export type Disk = {
  exists: (path: string) => Promise<boolean>;
  read: (path: string) => Promise<string>;
  list: (
    path: string,
  ) => Promise<readonly { name: string; kind: string; isLink: boolean }[]>;
};

/** A reader over the checkout `root`. A link counts as a file. */
export const localReader = (fs: Disk, root: string): Reader => ({
  list: async (dir) => {
    const at = dir === "" ? root : `${root}/${dir}`;
    if (!(await fs.exists(at))) return [];
    return (await fs.list(at)).map(
      (e): Entry => ({
        name: e.name,
        kind:
          e.kind === "file" || e.isLink
            ? "file"
            : e.kind === "dir"
              ? "dir"
              : "other",
      }),
    );
  },
  read: async (path) => {
    const at = `${root}/${path}`;
    return (await fs.exists(at)) ? await fs.read(at) : undefined;
  },
});
